    if (!race) return false;
    try { if (typeof unitRosterScope === 'function' && unitRosterScope() === 'all') return true; } catch (e) {}
    try { if (typeof isUnitOwned === 'function' && isUnitOwned(race)) return true; } catch (e) {}
