        html += '<div class="ew-elem-row ew-elem-rxs">' + band.map(c => '<span class="ew-elem-cell ew-elem-rx ' + esc(c.tier || 'unknown') + '" style="color:' + c.color + '" title="' + esc(c.tip) + '">' + esc(c.sym) + '</span>').join('') + '</div>';
