    /* ☢ RADIOACTIVE SLUDGE (2026-11-16, mondo on the Sewers' radioactive district: "make it a new liquid that does corrosion
       (I think that's poison and burned combined? that's close to radiation)"): a liquid of its own in the poison family.
       It first gave Corroded; since the radioactive status below it gives RADIOACTIVE. Flyers are spared (map.js
       applyTerrainTurnEffects skips anyone airborne). In a walked room it is a liquid nobody enters (any liquid but water: hqTerrainWalkable).
       Look: sprites.js TERRAIN_SPRITES.sludge + three-renderer.js _LIQUID_STYLES.sludge. */
    /* ☢ THE RADIOACTIVE STATUS (2026-11-16, mondo picked "Radiation: its own status", named it "radioactive", and ruled it is NOT
       Poison: "it needs its own bonus spells"): the sludge gives RADIOACTIVE, not Corroded. Each turn ended in it adds one stack
       (up to 3, STATUS_DEFS.radioactive); `stacks: true` tells the tile card + the move ghost to say "adds a stack". */
    sludge: {
        label: 'Radioactive Sludge',
        short: 'SLG',
        passable: true,
        moveCost: 2,
        blocksRanged: false,
        healMultiplier: 0.5,
        turnStatus: { id: 'radioactive', duration: 1, stacks: true },
        endTurn(unit) {
            return { type: 'status', id: this.turnStatus.id, duration: this.turnStatus.duration };   // one log line: applyStatusPayload's "Radioactive Sludge: X is RADIOACTIVE"
        }
    },
    /* Black liquid family (2026-07-14): 'swamp' is the Black Goo Ooze Trail's
       toxic slick (it previously had NO rule and fell back to grass), 'oil' is
       the paintable oil slick. Both render as black tinted water and DETONATE
       when hit by fire/lightning (see battle.js _reactFireOil). */
    swamp: {
        label: 'Black Ooze',
        short: 'OOZ',
        passable: true,
        moveCost: 2,
        blocksRanged: false,
        healMultiplier: 0.7,
        /* CHAMP_REWORK Phase 5 wave C (2026-09-08): the black goo's terrain.
           Goo Shot / Splash / the Oozing trail paint it TIMED (battle.js
           _paintTimedTerrain → state._timedTerrain, reverts to the tile's
           previous terrain at the round tick); Ooze Trail's slick stays
           permanent. Anyone who walks onto it (finishMoveAt reads
           enterStatus) or ends a turn on it is Gooed — except flyers and the
           ooze itself (contactStatus 'goo'). */
        enterStatus: { id: 'goo', duration: 2 },
        turnStatus: { id: 'goo', duration: 2 },   // read by endTurn + the tile info panel (battle.js tileEffectsAt)
        endTurn(unit) {
            if (typeof canFly === 'function' && canFly(unit)) return null;
            if (typeof unitPassiveValue === 'function' && unitPassiveValue(unit, 'contactStatus') === 'goo') return null;
            if (unit && unit.race === 'samurai slug') return null;   // 🐌 THE SLIME ROAD (2026-11-17): the slime is his
            return { type: 'status', id: this.turnStatus.id, duration: this.turnStatus.duration, text: `${unitDisplayName(unit)} is coated by the ooze` };
        }
    },
    oil: {
        label: 'Oil Slick',
        short: 'OIL',
        passable: true,
        moveCost: 2,
        blocksRanged: false,
        healMultiplier: 1,
        endTurn(unit) { return null; }
    },

