/* 💔 Broken (STATUS_DEFS.broken, 2026-10-09): while it lasts the unit has no passives at all. Raw status read — this is a
   hot path (canFly → getUnitPassives runs per unit per frame in places). */
function unitIsBroken(unit) {
    return !!(unit && unit.status && (unit.status.broken | 0) > 0);
}
function getUnitPassives(unit) {
    if (!unit) return [];
    if (unitIsBroken(unit)) return [];
    const out = [];
    const flies = (typeof window !== 'undefined' && typeof window.canFly === 'function')
        ? window.canFly(unit) : false;
    if (flies) out.push(PASSIVE_DEFS.flying);
    for (const id of (RACE_PASSIVES[unit.race] || [])) {
        if (out.length >= MAX_UNIT_PASSIVES) break;
        const def = PASSIVE_DEFS[id];
        if (def && out.indexOf(def) === -1) out.push(def);
    }
    /* THE PASSIVES (SPELL_LIBRARY_PLAN.md §4.5, Phase 4): the EQUIPPED passive rows (gear + family passives) after the
       inherent ones — MAX_UNIT_PASSIVES caps the inherent only (the rows have no cap since 2026-10-06). Each row
       is wrapped with its hooks at top level, so every hook key reads through unitPassiveValue unchanged. */
    for (const id of unitPassiveRowIds(unit)) {
        const w = passiveRowWrap(id, unitPassiveLevel(unit, id));
        if (w && out.indexOf(w) === -1) out.push(w);
    }
    return out;
}

function unitHasPassive(unit, id) {
    const list = getUnitPassives(unit);
    for (const p of list) if (p.id === id) return true;
    return false;
}

/* First defined value of `key` across the unit's passives (undefined if none).
   e.g. unitPassiveValue(u, 'basicAttackLifesteal') → 0.25 for vampires. */
function unitPassiveValue(unit, key) {
    /* 👁 PROJECTING: a spirit has the Ghost's two Incorporeal hooks (physical hits pass through, it drifts through walls
       and bodies), read from that passive's own row so the two can never drift apart */
    if (unit && unit.status && unit.status.projecting > 0 && (key === 'immuneDamageType' || key === 'phasing')
        && typeof PASSIVE_DEFS !== 'undefined' && PASSIVE_DEFS.incorporeal && PASSIVE_DEFS.incorporeal[key] !== undefined) {
        return PASSIVE_DEFS.incorporeal[key];
    }
    const list = getUnitPassives(unit);
    for (const p of list) if (p[key] !== undefined) return p[key];
    return undefined;
}

/* Does any of the unit's passives grant immunity to this status id? */
function unitPassiveBlocksStatus(unit, statusId) {
    const list = getUnitPassives(unit);
    for (const p of list) {
        if (p.immuneStatus && p.immuneStatus.indexOf(statusId) !== -1) return p;
    }
    return null;
}

/* THE TRAINING hooks (THE JOBS REMOVAL, 2026-09-27): how two passives that touch one number stack —
   Σ for flat bonuses (armor, spellPower, …), Π for multipliers (basicDmgMult, …), max for chances / caps. */
function _passiveNums(unit, key) {
    const out = [];
    for (const p of getUnitPassives(unit)) if (p && typeof p[key] === 'number' && isFinite(p[key])) out.push(p[key]);
    return out;
}
function unitPassiveSum(unit, key) { let n = 0; for (const v of _passiveNums(unit, key)) n += v; return n; }
function unitPassiveMult(unit, key) { let n = 1; for (const v of _passiveNums(unit, key)) n *= v; return n; }
function unitPassiveMax(unit, key) { let n = 0; for (const v of _passiveNums(unit, key)) if (v > n) n = v; return n; }

