/* ── SPD → MOVE (2026-08-29 stat rework, phase 3) ──────────────────────────
   Movement range is no longer a stored stat: one letter of SPD = one tile.
     SPD 1–25 → 1 · 26–40 → 2 · 41–60 → 3 · 61–80 → 4 · 81–100 → 5
     (the 1-tile band reaches 5 points into C since 2026-10-06, below).
   The old move-3 hard cap (2026-07-13: move 4+ crossed an 8×8 map in one
   turn) is replaced by a move-5 ceiling plus a halved SECOND move
   (ceil(move/2) tiles — see getMoveTiles in battle.js), so baseline A/S
   speedsters are allowed without restoring the map-crossing double-move. */
/* SPEED DRIVES MOVEMENT (mondo 2026-10-06: "a loch ness monster that is slow and moves close to last but can
   move a bunch of tiles"): the lumbering tail of the C band (SPD 21–25: Nessie, Kraken, King Kong, the golems
   and mechs) walked as far as a SPD-40 werewolf. The 1-tile band now runs to SPD 25; every other band is
   unchanged (26–40 → 2 · 41–60 → 3 · 61–80 → 4 · 81+ → 5). The ONE table every reader goes through. */
/* SPD → TILES (race editor 2026-10-06, mondo: "let me change the bands like everything else in the editor"). MOVE_SPD_RULE is
   the one live rule: follow = true → the tiles follow the SPD letters (STAT_GRADE_BANDS.spd: F walks 1 · C 2 · B 3 · A 4 ·
   S 5, so a grade edit moves the tiles); follow = false → `from` = the lowest SPD that walks 2 / 3 / 4 / 5 tiles. The race
   editor's GRADES tab edits it (EWRaceMods doc.move). MOVE_SPD_BANDS keeps the top SPD of each band for the old readers. */
const MOVE_SPD_RULE = { follow: true, from: [49, 88, 126, 163] };
const MOVE_SPD_BANDS = [48, 87, 125, 162];
function moveSpdFrom() {
    const g = (typeof STAT_GRADE_BANDS !== 'undefined' && STAT_GRADE_BANDS.spd) || null;
    const from = (MOVE_SPD_RULE.follow && g && g.length === 4) ? [g[3], g[2], g[1], g[0]] : MOVE_SPD_RULE.from;
    for (let i = 0; i < 4; i++) MOVE_SPD_BANDS[i] = from[i] - 1;
    return from;
}
function moveFromSpd(spd) {
    const s = Math.max(1, spd || 1);
    moveSpdFrom();
    let tiles = 1;
    for (const top of MOVE_SPD_BANDS) if (s > top) tiles++;
    return Math.min(5, tiles);
}

/* THE JUMP STAT (2026-10-17, mondo: "how is a unit's jump stat/range/height calculated? can i see it in the race editor
   along with the other stats?"). Moved here from battle.js (RACE_JUMP_OVERRIDE + RACE_NIMBLE_JUMP, same values) so the race
   editor can show and edit it. JUMP = the levels a unit hops UP (Jump action + a Move's jump legs); its leap reach is
   max(2, JUMP) tiles (battle.js getUnitJumpReach). RACE_JUMP is the race's own jump; a race not listed jumps 1 below
   JUMP_SPD_FROM SPD and 2 from it. Read by battle.js getUnitJumpStat (after an explicit unit.jump). */
const RACE_JUMP = {
    // Colossal: a single bound crosses chasms and clears tall roofs.
    'kaiju': 3, 'king kong': 3, 'kraken': 3, 'dragon': 3,
    'loch ness monster': 3, 'juggernaut': 3, 'giant': 3, 'titan': 3,
    // Large, long-limbed bruisers.
    'cyclops': 2, 'bigfoot': 2, 'yeti': 2, 'dinosaur': 2,
    'minotaur': 2, 'nephilim': 2, 'golem': 2, 'mech': 2,
    'goatman': 2, 'symbiote': 2,
    // The nimble races (kept explicitly since the 2026-08-29 stat rework).
    'skeleton': 2, 'werewolf': 2, 'mothman': 2, 'siren': 2, 'android': 2,
    'shadow entity': 2, 'catgirl': 2, 'mantid': 2, 'skinwalker': 2, 'glitch': 2,
    'pirate': 2, 'swordfighter': 2, 'men in black': 2, 'marksman': 2, 'spy': 2, 'halfdemon': 2,
    'fallen angel': 2, 'cosmic wraith': 2, 'cyborg': 2, 'chosen one': 2, 'ghoul': 2,
    'barbarella': 2, 'ki fighter': 2, 'robinhood': 2, 'valkraye': 2,
    // On wheels: a cart rolls up one step and no higher (2026-11-17 THE CURSED TV).
    'cursed tv': 1,
};
const JUMP_SPD_FROM = 90;       // a race with no RACE_JUMP row jumps 2 from this SPD, else 1
const RACE_JUMP_RANGE = [1, 5]; // the race editor's limits
function raceJumpStat(race, spd) {
    const j = RACE_JUMP[race];
    if (j != null) return j;
    return (spd == null ? 50 : spd) < JUMP_SPD_FROM ? 1 : 2;
}

function computeUnitStats(race, cls, zodiac) {
    const base0 = RACE_BASE_STATS[race] || RACE_BASE_STATS['door agent'];
    /* the birth sign's natal changes (ZODIAC_EFFECTS[sign].natal) ride on the base, so the level formula scales them too */
    const base = zodiac && ZODIAC_EFFECTS[zodiac] ? Object.assign({}, base0) : base0;
    if (base !== base0) ZODIAC_NATAL_KEYS.forEach(k => { const d = zodiacNatalDelta(zodiac, k); if (d) base[k] = Math.max(k === 'hp' ? 1 : 0, (base[k] || 0) + d); });
    const kit = raceKit(race);   // THE JOBS REMOVAL (2026-09-27): the reach is the race's (RACE_KITS); `cls` is ignored
    const spd = Math.max(1, base.spd || 50);   // no 0–100 cap since the 2026-10-06 race editor scale (SPD runs to 200)
    return {
        // Base stats are FINAL — RACE_BASE_STATS already carries what the old primary job baked in.
        hp: base.hp,
        mp: base.mp,
        atk: base.atk,
        def: base.def,
        mdef: base.mdef || 0,
        // Derived, never stored: base tiles from the SPD band (rework 2026-08-29).
        move: moveFromSpd(spd),
        vision: Math.max(1, base.vision != null ? base.vision : 3),
        crt: Math.max(0, base.crt != null ? base.crt : 8),
        int: base.int,
        spd,
        range: kit.range,
        inspect: kit.inspect
    };
}

function computeEquipBonuses(equipment) {
    const bonuses = { hp: 0, mp: 0, atk: 0, def: 0, mdef: 0, move: 0, vision: 0, crt: 0, int: 0, spd: 0 };
    if (!equipment) return bonuses;
    for (const slot of ['accessory1', 'accessory2']) {
        const itemId = equipment[slot];
        if (!itemId) continue;
        const def = EQUIP_DEFS[itemId];
        if (def && def.stat && def.statVal) {
            bonuses[def.stat] = (bonuses[def.stat] || 0) + def.statVal;
        }
    }
    return bonuses;
}

function formatEquipStat(itemId) {
    const def = EQUIP_DEFS[itemId];
    if (!def || !def.stat || !def.statVal) return '';
    return '+' + def.statVal + ' ' + def.stat.toUpperCase();
}

