/* THE ITEM EDITOR (2026-10-08, the Data Panel's ITEMS tab): a NEW item copies a shipped item's behaviour with `like` (one of
   ITEM_LIKE_KEYS) and carries its own numbers (healPct, mpPct, revivePct, max, price, …). Throws (baneType), stims (selfBoost)
   and capture doors (kind) were data-driven already. Every check that used to name one of these shipped keys reads
   itemBase(key) instead, so a new potion heals, targets, shows in the HUD and gets used by the CPU like the one it copies.
   The scanner, panacea and warp stone stay one of a kind (their code runs on the item's own key). */
const ITEM_LIKE_KEYS = ['healPotion', 'manaPotion', 'reviveTonic', 'elixir'];
function itemBase(key) {
    const r = ITEM_RULES[key];
    return (r && typeof r.like === 'string' && ITEM_LIKE_KEYS.includes(r.like)) ? r.like : key;
}
function itemKeysLike(base) { return Object.keys(ITEM_RULES).filter(k => itemBase(k) === base); }

function getRaceLabel(race, gender) {
    const p = RACE_PROFILES[race];
    if (!p) return race || '?';
    if (gender === 'female' && p.labelFemale) return p.labelFemale;
    if (gender === 'male' && p.labelMale) return p.labelMale;
    return p.label || race;
}

/* ── Spell `element` tags ─────────────────────────────────────────────────
   Optional field on any spell: element: 'fire'|'ice'|'lightning'|'water'|
   'earth'|'wind'|'poison'|'nature'|'psychic'|'sonic'|'blood'|'metal'
   (canonical list: SPELL_ELEMENTS, near TYPE_CHART). `vfxElement:` ('light' |
   'shadow' | 'arcane', the three cut 2026-10-18) is the look only.
   Since 2026-09-01 the COMBAT_ELEMENTS (fire/ice/lightning/water/poison/
   earth, plus wind/nature/sonic/psychic/blood/metal since 2026-10-17) are a real combat layer: damage of those elements consults
   RACE_ELEMENT_AFFINITY (weak ×1.25 / resist ×0.75 / immune / absorb),
   water-element damage Soaks the target, and elemental statuses couple to
   affinities — see the ELEMENTAL AFFINITIES block + ELEMENTAL_TYPES_PLAN.md.
   Every tag also themes VFX (_resolveTheme), SFX and library filters; an
   untagged spell is elementally neutral.
   The element layer is SECONDARY: the type chart + STAB always apply on top.
   The tag is authoritative for battle.js getSpellElement — the legacy
   name-keyword sweep only guesses for UNTAGGED spells now (a tag can no
   longer be overridden by an unlucky name like Radiant "Bolt").
   RULE for new content: every new DAMAGE spell either carries an element:
   tag or a deliberate `// element: none` note. A combat-element spell that
   applies a status should apply its paired one (fire→burn, ice→frozen,
   poison→poison, lightning→stun; water soaks automatically). */
