const NEXUS_GOLD_PER_ROUND = 5;
const NEXUS_CHANNEL_COST_AP = 1;
/* ── NEXUS REWORK (2026-09-12) — Arena's zones are the whole economy ──
   A zone flips at NEXUS_CAPTURE_THRESHOLD ticks (was 6). Ticks come from
   THREE sources, all through ui.js `_nexusApplyTicks`: a channel (1 AP =
   +1), STEPPING INTO the zone (+1 per unit per round, ui.js
   `nexusOnUnitArrive` — four bodies on a 2×2 zone flip it on the spot),
   and standing there at the round transition (+1 / +2 for two or more,
   `processNexusIncome`). Owning a zone: every ally standing in it heals
   NEXUS_HOLD_HEAL_PCT HP + MP and is cleansed at the round end; an enemy
   standing in a zone YOU own burns NEXUS_HOSTILE_DMG_PCT of max HP. There
   is no instant win any more — the SPAWN LOCKOUT is the prize: a team
   respawns only on a zone it owns (home spawn first, then the centre —
   map.js `getRespawnZoneFor`), so a team with no zone is stuck with the
   units still on the field. Each non-home zone held also multiplies the
   team's Cube damage (+NEXUS_CUBE_DMG_PER_ZONE, ui.js `getCubeDamageMult`).
   Zones are BUILDABLE: reshape / dig / flood / block all work on nexus and
   spawn tiles (battle.js `isObjectiveTile` guards the Cubes only). */
const NEXUS_CAPTURE_THRESHOLD = 4;
const NEXUS_ZONE_SIZE = 2;
const NEXUS_HOLD_HEAL_PCT = 0.15;      // allies in a zone you own: +15% max HP & MP + cleanse per round
const NEXUS_HOSTILE_DMG_PCT = 0.25;    // enemies in a zone you own: 25% max HP per round (armour ignored)
const NEXUS_CUBE_DMG_PER_ZONE = 0.5;   // Cube damage ×(1 + 0.5 per non-home zone held) → ×1.5 / ×2
const NEXUS_CUBE_DMG_MAX_MULT = 2.0;

/* ── RESERVES (the bench in the respawn modes, 2026-09-14) ──────────────
   Match-select CONFIG → RESERVES: Off / Bench. A reserves match fields a
   roster of `roster` per side; `deploy` stand on the board, the rest wait
   on the bench (state.bench — the Gauntlet plumbing in battle.js). Three
   rules, all read through battle.js `_benchOn()` / `doSwitch` /
   `_reserveQueueSeat` / map.js `processRespawns`:
   1. THE BENCH IS A ROTATION, NOT A HOSPITAL — a switched-out unit keeps
      its HP / MP / lingering statuses (stat stages + shield reset, as in
      Gauntlet); nothing on the bench heals.
   2. DEATH OWES THE LADDER, THE LADDER FOLLOWS THE SEAT — a fallen unit
      still waits its 2 / 3 / 5 / 8 rounds (and the Nexus spawn lockout);
      when the clock runs out a reserve may TAKE THE SEAT instead (the
      player chooses at the death, the AI takes a reserve above
      `seatMinHpPct`); the fallen unit then revives ON THE BENCH. One body
      returns per death, on the ladder's clock, at a zone the team holds.
   3. SWITCHING COSTS THE TURN, NOT A SPAWN — `switchApCost` AP, the
      incoming unit acts with the leftover AP, and at most
      `switchesPerRound` voluntary switches per team per round. */
const RESERVE_RULES = {
    roster: 8,            // units per side in a reserves match (the archive's cap)
    deploy: 4,            // on the board at once
    switchApCost: 2,      // ⇄ SWITCH — same as Gauntlet
    switchesPerRound: 1,  // voluntary switches per team per round (Gauntlet stays uncapped)
    seatMinHpPct: 0.6,    // the AI sends a reserve into a dead seat only above this HP
};
if (typeof window !== 'undefined') window.RESERVE_RULES = RESERVE_RULES;

// ── ARENA COMPOSITE SCORING — single source of truth ──────────────────
// Read by the timer-expiry resolver + victory screen (battle.js) and the
// live scoreboard (hud.js). Cube damage is UNCAPPED (mondo 2026-10-23: the
// old 150 cap is gone; a full Cube is 250 points at 1 per 0.4% of its HP, and
// destroying it outright is still an instant win); nexus control is the strongest per-round engine, and
// accrual doubles in the final rounds (see tickMatchClock) so a trailing
// team holding zones can close the gap.
// Display names for nexus zone keys (zones are placed on a diagonal across
// the fully-3D board: one always dead-center, one toward each corner).
window.NEXUS_LABELS = {
    earth: 'Central', nw: 'Northern', se: 'Southern',
    west: 'Western', east: 'Eastern', north: 'Northern', south: 'Southern',
    above: 'Sky', below: 'Cave', roaming: 'Hotspot',
    spawn1: 'P1 Spawn', spawn2: 'P2 Spawn',
};

window.ARENA_PTS = {
    kill: 25,           // per kill (15 → 25 on 2026-10-07, mondo)
    towerDmgPer10: 1,   // points per 0.4% of the enemy Cube's HP lost (250 for a whole Cube); no cap since 2026-10-23 (mondo)
    hourglass: 35,      // per hourglass carried at the buzzer
    nexusRound: 6,      // per nexus-control round accrued
    surgeLastRounds: 5, // final N rounds: nexus accrual is doubled ("Nexus Surge")
    bounty: 15,         // per bounty claimed (killing an ON FIRE unit) at a 3-kill streak — on top of the kill's 25 (mondo 2026-10-06: comebacks)
    bountyPerStreak: 5, // …+5 for each streak kill past 3, like the gold bounty (mondo 2026-10-06: "the bounty keeps going up")
    bountyCap: 35,      // …up to here
};

// ── ACCOUNT ECONOMY (PvP) ──────────────────────────────────────────────
// Single source of truth for the persistent, account-level unlock economy.
// Challenge mode keeps its OWN separate wallet (state.campaignSave / save.gold)
// and must never read from or write to anything below.
const ACCT_UNIT_PRICE        = 5000;  // flat cost of EVERY unit. Same for all, intentionally.
const ACCT_BASE_COMPLETE     = 50;    // flat gold for finishing a PvP match (win OR loss)
const ACCT_WIN_MULT          = 1.5;   // multiplier applied to (base + collected) on a win
const ACCT_FLAWLESS_MULT     = 1.25;  // win-only: no friendly unit died. STACKS.
const ACCT_WIPEOUT_MULT      = 1.25;  // win-only: all enemy units dead. STACKS.
const ACCT_STARTING_GOLD     = 0;     // wallet balance for a brand-new account
const ACCT_FREE_TOKENS       = 1;     // free-unlock tokens granted at account creation
const ACCT_MATCH_GOLD_CAP    = 5000;  // server-side sanity cap on banked gold per match (anti-cheat)

// New accounts own these race keys (each playable in its default job).
// 2026-07-05: expanded to cover every race with a rigged 3D model wired (or
// planned) in sprites.js RACE_MODELS_3D.
// THE ROSTER LOCK (2026-09-20 — the user: "lock all the units, except for
// during PvP online play (whole roster available to everyone) and VS CPU (so I
// can test stuff); otherwise you should be restricted to the units you have
// actually unlocked through Hazard Pay or a ticket"). The STARTERS are the two
// vessels that are YOU — the DOOR Agent (the officer, THE PARTY's slot 1) and
// the Homosapien (the recruit, the mirror's look) — plus three free hires the
// user named: the catgirl, bigfoot and the Sedan. Everything else is bought
// at the Quartermaster (gold = Hazard Pay, or the free ticket) — the old rule
// ("every rigged race is a starter") is gone; unitRosterScope() below opens the
// whole roster for an ONLINE seat and for the classic VS CPU / Room 64 range.
// Keep server.js ACCT_STARTER_UNITS in sync (npm run test:parity) — the server
// unions this list into an existing account on login (it never removes).
const ACCT_STARTER_UNITS = [
  'door agent',     // Agent — the officer (HOMOSAPIEN OUT 2026-10-23: the Homosapien recruit is gone)
  'catgirl',        // Gunslinger — the user's three free hires (2026-09-20)
  'bigfoot',        // Harvester
  'honda civic',    // the Sedan
];

/* ══ THE DEMO (mondo 2026-11-10: the PvP demo set — "everyone can start off with the same 16 and can unlock up to 32") ══════════
   An OPTIONAL filter, never a deletion: with the Demo switch on, the roster is these 32 champs and the map lists deal these
   arenas; with it off the whole game is there as before. Nothing in AVAILABLE_RACES, the spell lists or the maps is touched.
     starters  the 16 every player fields from the first match (owned by everyone while the Demo is on)
     unlocks   the 16 more a player unlocks the way units are already unlocked (the Shop: ACCT_UNIT_PRICE / a free token)
     arenas    the site ids the map lists deal (the 12×12 arenas of seven sites + the Training Room and the Holo Sim, which
               are 8×8 VS CPU boards: an online room only deals 9–12 boards, so online plays the seven)
     on        the SHIPPED default. false = off for everyone until a browser turns it on (Settings > Display > Demo, or
               ?demo=1 / ?demo=0 in the address); true = the whole game ships as the demo (the server's Quick Play pool reads
               hqArenaPvpPool, so it deals the demo arenas too).
   Online the HOST's switch decides for the room (it rides friendly-config as `demo`; a guest reads NET._roomDemo).
   The reads: demoModeOn() · demoRaceIn(race) · demoRaceFree(race) · demoArenaIn(mapId) · demoRacePool(list). */
const DEMO_RULES = {
    on: false,
    starters: ['knight', 'zombie', 'bigfoot', 'door agent', 'catgirl', 'shadow entity', 'robinhood', 'martian',
               'djinn', 'mummy', 'angel', 'mermaid', 'grey', 'mothman', 'honda civic', 'quarterback'],
    unlocks:  ['general', 'nephilim', 'ki fighter', 'king kong', 'goatman', 'mantid', 'cosmic wraith', 'anubis',
               'professor', 'starfish', 'dreameater', 'hippie', 'mushroom girl', 'ai', 'glitch', 'sidekick'],
    arenas:   ['prebuilt_training', 'prebuilt_holosim', 'prebuilt_lookingglass', 'prebuilt_fairy_forest', 'prebuilt_technoticlan',
               'prebuilt_stonehenge', 'prebuilt_revenge', 'prebuilt_northpole', 'prebuilt_hell'],
};
(function _demoBootRead() {   // the browser's own switch: ?demo=1|0 wins and is remembered, else the stored choice
    if (typeof window === 'undefined') return;
    try {
        const q = (typeof location !== 'undefined' && location && typeof location.search === 'string') ? /[?&]demo=([01])\b/.exec(location.search) : null;
        if (q) { window._ewDemoMode = q[1] === '1'; try { localStorage.setItem('ew_demo_mode', q[1]); } catch (e) {} return; }
        const s = localStorage.getItem('ew_demo_mode');
        if (s === '1' || s === '0') window._ewDemoMode = s === '1';
    } catch (e) {}
})();
function demoModeOn() {
    if (typeof window === 'undefined') return !!DEMO_RULES.on;
    try { const N = window._NET; if (N && N.online && N.role === 'guest' && typeof N._roomDemo === 'boolean') return N._roomDemo; } catch (e) {}
    if (typeof window._ewDemoMode === 'boolean') return window._ewDemoMode;
    return !!DEMO_RULES.on;
}
function setDemoMode(on) {
    if (typeof window === 'undefined') return;
    window._ewDemoMode = !!on;
    try { localStorage.setItem('ew_demo_mode', on ? '1' : '0'); } catch (e) {}
}
const _demoKey = r => String((r && typeof r === 'object' ? r.race : r) || '').toLowerCase();
function demoRaceFree(race) { return DEMO_RULES.starters.indexOf(_demoKey(race)) >= 0; }
function demoRaceIn(race) { const k = _demoKey(race); return DEMO_RULES.starters.indexOf(k) >= 0 || DEMO_RULES.unlocks.indexOf(k) >= 0; }
/* a map id (a site, its `_delta` arena or a `_NxN_delta` cut) belongs to a demo site */
function demoArenaIn(mapId) {
    const id = String(mapId || '');
    if (typeof EW_MAP_META !== 'undefined') { const row = EW_MAP_META.find(m => m && m.id === id); if (row && row.voxel) return false; }   // a site's old "Δ · voxel" board is not its arena
    const site = (typeof hqSiteId === 'function') ? hqSiteId(id) : id.replace(/(_\d+x\d+)?_delta$/, '');
    return DEMO_RULES.arenas.indexOf(site) >= 0 || DEMO_RULES.arenas.indexOf(id) >= 0;
}
/* a pool of races cut to the demo roster while the Demo is on (the CPU's picks, the random rolls); never an empty pool */
function demoRacePool(list) {
    if (!demoModeOn() || !Array.isArray(list)) return list;
    const cut = list.filter(demoRaceIn);
    return cut.length ? cut : list;
}
if (typeof window !== 'undefined') { window.DEMO_RULES = DEMO_RULES; window.demoModeOn = demoModeOn; window.setDemoMode = setDemoMode; window.demoRaceIn = demoRaceIn; window.demoRaceFree = demoRaceFree; window.demoArenaIn = demoArenaIn; window.demoRacePool = demoRacePool; }

// PvP modes that bank account gold. Gauntlet/Challenge route through their own
// campaign economy and are intentionally excluded here.
const ACCT_PVP_MODES = ['arena', 'tdm', 'clash'];

// One ownership check everything routes through. View-layer only — purchasing is
// always server-authoritative; this just decides what shows as owned/selectable.
/* THE ROSTER SCOPE (2026-09-20): where the whole roster is open. 'all' = an
   ONLINE seat (isOnlineMatch — the lobby's setup phase already seats the
   remote controller), the classic VS CPU route and Room 64's RANGE console
   (map.js sets window._ewRosterScope = 'all' there), the dev switch;
   'owned' = everything else — the building, THE PARTY, the encounters, the
   crossings filed from a site's console or the DISPATCH desk (map.js sets
   'owned' on every entry / launch). The shop always reads isUnitOwned. */
function unitRosterScope() {
  if (typeof window === 'undefined') return 'owned';
  if (window._DEV_UNLOCK_ALL) return 'all';
  try { if (typeof window.isOnlineMatch === 'function' && window.isOnlineMatch()) return 'all'; } catch (e) {}
  try { if (window._NET && window._NET.online) return 'all'; } catch (e) {}   // the online lobby (its forge seats the remote controller only at setup)
  return window._ewRosterScope === 'all' ? 'all' : 'owned';
}
// The LEDGER read: is the vessel on the account (a starter offline)? Never the scope.
// THE OWNED READ (2026-10-25, the seamless pass): a fight's launch asks isUnitOwned for every seat and race (the party repair, the
// roster scope), and each call parsed the whole stored profile again (~250 ms of the sandbox's strike hitch) — the parse is kept
// while the stored text is the same text. Read-only: isUnitOwned never writes the profile it reads.
let _ownedProfMemo = { raw: null, prof: null };
function _ownedProfileRead() {
  const PS = (typeof window !== 'undefined') ? window.ProfileSystem : null;
  if (!PS || typeof PS.getActiveProfile !== 'function') return null;
  let raw = null;
  try { const i = (typeof PS.getActiveProfileIndex === 'function') ? PS.getActiveProfileIndex() : null; raw = (i === null || i === undefined) ? null : localStorage.getItem('ew-profile-' + i); } catch (e) { raw = null; }
  if (raw !== null && raw === _ownedProfMemo.raw && _ownedProfMemo.prof) return _ownedProfMemo.prof;
  const prof = PS.getActiveProfile() || {};
  _ownedProfMemo = { raw: raw, prof: raw !== null ? prof : null };
  return prof;
}
function isUnitOwned(raceKey) {
  if (typeof window !== 'undefined' && window._DEV_UNLOCK_ALL) return true; // dev override, view-layer only
  if (typeof isRace3DReady === 'function' && !isRace3DReady(raceKey)) return false;
  if (demoModeOn() && demoRaceFree(raceKey)) return true;   // THE DEMO: the 16 starters are everyone's
  const prof = _ownedProfileRead();
  const acct = prof ? prof.account : null;
  /* THE ONE-WAY DOOR (2026-09-25, the user: "if you caught an enemy then why would you need to buy it in the shop? It should
     already be unlocked"): a race a capture door SEALED is owned — the captured ledger (local + the synced blob) is the claim */
  /* PRIEST + NUN MERGED (2026-10-27): a unit owned under an old key (RACE_MERGED: the nun) owns the race it became */
  const keys = [raceKey].concat(Object.keys(RACE_MERGED).filter(k => RACE_MERGED[k].race === raceKey));
  try { if (prof && typeof hqUnitCaptured === 'function' && keys.some(k => hqUnitCaptured(prof, k))) return true; } catch (e) {}
  if (!acct || !Array.isArray(acct.unlockedUnits)) return keys.some(k => ACCT_STARTER_UNITS.includes(k)); // offline fallback
  return keys.some(k => acct.unlockedUnits.includes(k));
}
function isUnitUnlocked(raceKey) {
  if (typeof window !== 'undefined' && window._DEV_UNLOCK_ALL) return true; // dev override, view-layer only
  if (typeof isRace3DReady === 'function' && !isRace3DReady(raceKey)) return false;
  /* THE DEMO: the roster is the 32 — the 16 starters free, the 16 unlocks once they are on the account (isUnitOwned),
     online and VS CPU alike; nothing outside the 32 is fielded while the switch is on */
  if (demoModeOn()) return demoRaceIn(raceKey) && isUnitOwned(raceKey);
  if (unitRosterScope() === 'all') return true;   // THE ROSTER LOCK: online / the classic VS CPU / the range = the whole roster
  return isUnitOwned(raceKey);
}

// Exact reward formula (§0 of the spec). Mirrors what the server clamps on /bank.
function computeAccountMatchGold(opts) {
  opts = opts || {};
  const collected = Math.max(0, Math.round(opts.collected || 0));
  const playerWon = !!opts.playerWon;
  const noFriendlyDeaths = !!opts.noFriendlyDeaths;
  const allEnemiesDead = !!opts.allEnemiesDead;

  const winMult = playerWon ? ACCT_WIN_MULT : 1.0;
  let condMult = 1.0;
  if (playerWon && noFriendlyDeaths) condMult *= ACCT_FLAWLESS_MULT;
  if (playerWon && allEnemiesDead)   condMult *= ACCT_WIPEOUT_MULT;

  const total = Math.round((ACCT_BASE_COMPLETE + collected) * winMult * condMult);
  const matchGold = Math.min(total, ACCT_MATCH_GOLD_CAP);

  return {
    collected,
    base: ACCT_BASE_COMPLETE,
    winMult,
    flawless: playerWon && noFriendlyDeaths,
    wipeout: playerWon && allEnemiesDead,
    condMult,
    matchGold,
    capped: total > ACCT_MATCH_GOLD_CAP,
  };
}

