/* ═══════════════ 7.7 WAVE 2 — THE NEW SITES (2026-09-16) ═══════════════ */

/* THE BERMUDA TRIANGLE — 16×16 6v6. "It's a right triangle" — and it IS:
   the board is TWO right triangles of shoal meeting at a diagonal of DEEP
   water from the north-east corner to the south-west (the hypotenuse of
   each), the legs the board's own edges, the 90° corners at the north-west
   (P2's) and the south-east (P1's) — a lantern buoy on each. The deep runs
   the whole diagonal but for a two-tile SANDBAR at the centre, the one
   crossing a ground unit has; flyers cross anywhere. On each shoal: a
   wreck (the hull two high, its deck one), rocks, sandbars, tide pools. The
   sea streams past at half the Dutchman's pace, the storm builds from
   round 3 (env.motion). */
_MF_BUILDERS.prebuilt_bermuda = function () {
    const M = _mfNew({
        name: 'The Bermuda Triangle', w: 16, h: 16, base: 'desert', baseH: 3, seed: 345,
        strata: ['deep_water', 'deep_water', 'rocks_1'], underTop: 'rocks_1',
        tints: { desert: '#f2ead6', water: '#5fc8d0', deep_water: '#123c5a', wood: '#6a4a30', rocks_1: '#8a8478', dirt_2: '#cfae7c' },
    });
    /* THE ISLANDS (2026-09-16, the user: "how is there no water in the
       Bermuda Triangle? it should be a lot of water; it can double as an
       island / buried treasure map"): the board is the OPEN SEA now — a
       beach each side (the spawn rows), a treasure island in the middle
       with the X on it (dirt_2, the chest stands on it), a wreck on a rock
       islet each side, shallows (wade) round every shore and the deep
       between. The top half is a sheet; sym180 paints P1's. */
    const ROWS = [
        '~~~SSSSSSSSSS~~~',   // 0  P2's beach — the spawn row (x 5..10)
        '~~SSSSSSSSSSSS~~',   // 1
        'D~~SSSSSSSSSS~~D',   // 2
        'DD~~~bb~~~~~~~DD',   // 3  the west sandbar (b): dry the whole way; the east way is a wade
        'DDD~~bb~~~~~~~DD',   // 4
        'RSD~~~SSSS~~~DDD',   // 5  the wreck's islet (R a rock, S its sand); the island's north shore
        'WwD~~SSSSSS~~DDD',   // 6  W the hull (+2), w its deck (+1)
        'DDD~~SSXXSSS~~DD',   // 7  X marks the spot (with its twin: the 2×2 at the centre)
    ];
    const sea = (x, y, deep) => { M.t(x, y, deep ? 'deep_water' : 'water'); M.h(x, y, 2); if (deep) M.under(x, y, 1, 'deep_water'); };
    ROWS.forEach((row, y) => {
        for (let x = 0; x < 16; x++) {
            const ch = row[x];
            if (ch === '~') sea(x, y, false);
            else if (ch === 'D') sea(x, y, true);
            else if (ch === 'b' || ch === 'X') M.t(x, y, 'dirt_2');
            else if (ch === 'R') M.rect(x, y, x, y, 'rocks_1', 4);
            else if (ch === 'W') M.rect(x, y, x, y, 'wood', 5);
            else if (ch === 'w') M.rect(x, y, x, y, 'wood', 4);
        }
    });
    M.sym180();
    // the buoys: a lantern at each 90° corner and off the west/east shores, a torch on each beach
    M.objSym(0, 0, 'torch', { leaf: 'floor' });
    M.objSym(0, 7, 'torch', { leaf: 'floor' }); M.objSym(7, 0, 'torch', { leaf: 'floor' });
    M.spawnEdges('s', 6);
    M.finishSpawns('desert');
    return M;
};

/* ═══════════════════════════════════════════════════════════════════════════
   DELTA FORGE — hand-authored 8×8 Δ boards (2026-09-01 delta redesign)
   ─────────────────────────────────────────────────────────────────────────────
   Every launch map's Δ used to be a blind 8×8 crop of its full map. They are
   now AUTHORED, Custom-Robo-Arena style: a flat 8×8 chess board with a few
   obstacles that break line of sight and shape lanes — and nothing else.
   House rules (validated headlessly — see PLAYTEST_NOTES "DELTA FORGE"):
     • 8×8, 4v4. P2 spawns on row 0 (x 2..5), P1 on row 7. The spawn rows,
       the egress rows behind them (rows 1 / 6, x 2..5) and the 2×2 nexus
       zone at dead centre (x 3..4, y 3..4) are ALWAYS flat at the shared
       baseline, clear of objects, and never walled off. Arena stamps the
       centre nexus from the authored `nexus` object; TDM & co. strip it.
     • 180°-rotation symmetric (terrain, heights, objects, walls, monuments).
     • At least two node-disjoint walkable routes from each spawn row to the
       nexus for a jump-1 ground unit.
     • Vocabulary (heights relative to the baseline surface z = MF_DELTA_BASE_H):
         M.step(x,y,tex)      +1 ledge — climbable cover. A 1-high bump hides
                              two flat-ground units; standing on it sees over.
         M.block(x,y,tex)     +2 solid block — a wall for jump-1 units (most),
                              jump-2 races hop onto it. Blocks sight. A step
                              beside it is a staircase onto it.
         M.block(x,y,tex,3)   +3 — a wall for everyone.
         M.wall(x,y,side,o)   THIN edge wall (h 2 = blocks walking + sight and
                              costs no floor tile; see:true = chain-link that
                              blocks walking only; h 1 = hop-over parapet).
         M.tree(x,y,kind)     tree object — blocks walking + sight.
         M.pillarSym(kind,…)  ONLY collision monuments are allowed here
                              (tpillar, greekcol, mushroom, mushroom2, obelisk3d,
                              monolith, greytube, cargo, dumpster, the chess_* pieces):
                              they stamp real voxels, so what looks like cover
                              IS cover. M.pieceSym(kind, x, y, h) is a chess
                              piece + its twin (dark / light).
         M.lake(x,y,tex,d)    1-deep pond (walkable, escapable); depth 2 also
                              floods the dirt_4 stratum so the board's cut edge
                              shows a real lake sunk into the bed.
     • Shared bed under every board: lava → cave floor → cave wall → dirt →
       dirt, then the themed surface at z5. Raised blocks wear their own
       surface texture all the way down (cfg.fillAbove = 'surface').
     • Author the TOP HALF (rows 0..3) only, then M.symAll(); monuments go
       AFTER symAll via pillarSym / mon pairs; M.finishDelta() seats spawns,
       scrubs the protected tiles and places the centre nexus.
   ═══════════════════════════════════════════════════════════════════════════ */
const MF_DELTA_S = 8;
const HQ_ARENA_SIZE = 12;   // the PvP arena a side (mondo 2026-10-06: "make all arena maps 12x12") — HQ_ARENA_RULES.size and the kept boards read it
/* THE ARENA SIZES (mondo 2026-10-17: "i would like to add 9x9, 10x10, and 11x11 maps ... an option to play 5v5 ... for the 9x9 and
   11x11 map to make it symmetrical ... The 10x10 is for 4v4"): every site with a 12×12 cut also gets a 9, a 10 and an 11 cut of
   the same room (bake-arenas.js --size N, HQ_ARENA_RULES.picks9 / picks10 / picks11). The odd boards are 5v5 (hqArenaHouse: a 2×3
   spawn zone each side, the Cube on its back-middle tile, the 5 on the other five, a 3×3 nexus at dead centre); 10 and 12 are 4v4
   on the row of four. A size not named here is 4v4. THE FAIRY FOREST (2026-10-24): 20 is the full site's 6v6 (a row of six,
   HQ_ARENA_RULES.own.prebuilt_fairy_forest) — never an arena size, so the PvP pool never deals it. */
const HQ_ARENA_EXTRA_SIZES = [9, 10, 11];
const HQ_ARENA_TEAM_BY_SIZE = { 9: 5, 10: 4, 11: 5, 12: 4, 20: 6 };
const MF_DELTA_BASE_H = 5;
const MF_DELTA_STRATA = ['lava', 'cave_floor', 'cave_wall', 'dirt_4', 'dirt_3'];
/* MOVING MAPS (2026-09-12): a Δ may carry its OWN five-layer bed (cfg.strata
   + cfg.underTop on _mfDeltaNew) — deep water and wood under a ship's deck,
   void and hull plate under a wreck, void and marble under a flying board.
   The entry records it as `bed`; delta-maps.test.js checks each board
   against its own bed (the shared lava bed stays the default). */
/* monument kinds with a real collision stamp (map.js _MON_COLLISION / _MON_GRID) */
const MF_DELTA_SOLID_MONS = new Set(['tpillar', 'greekcol', 'mushroom', 'mushroom2', 'obelisk3d', 'monolith', 'greytube', 'cargo', 'dumpster', 'obelisk', 'fallen_column', 'greek',
    'menhir', 'castle_wall', 'gothic_wall', 'ziggurat_block',   // THE SPELL-MADE MONUMENTS (2026-09-18): the wall spells' pieces, placeable by the forge / editor too
    'chess_pawn', 'chess_rook', 'chess_knight', 'chess_bishop', 'chess_queen', 'chess_king']);   // the Looking-Glass's pieces (2026-09-12)

function _mfDeltaNew(cfg) {
    const S = cfg.S || MF_DELTA_S, B = MF_DELTA_BASE_H;   // cfg.S: a bigger board (the kept PvP arenas are HQ_ARENA_RULES.size a side)
    const M = _mfNew({
        name: cfg.name, w: S, h: S, base: cfg.base || 'grass_2', baseH: B, seed: cfg.seed || 8008,
        strata: cfg.strata || MF_DELTA_STRATA, underTop: cfg.underTop || 'dirt_3', fillAbove: 'surface', tints: cfg.tints || null,
    });
    M.B = B;
    M.deltaDesc = cfg.desc || '';
    M.block = (x, y, key, h) => { if (key) M.t(x, y, key); M.h(x, y, B + (h == null ? 2 : h)); };
    M.step = (x, y, key) => { if (key) M.t(x, y, key); M.h(x, y, B + 1); };
    M.lake = (x, y, key, depth) => {
        key = key || 'water';
        M.t(x, y, key); M.h(x, y, B - 1);
        if ((depth || 1) >= 2) M.under(x, y, B - 2, key);
    };
    M.treeL = (x, y, kind, leaf) => M.obj(x, y, kind || 'tree', leaf ? { leaf } : null);
    M.wrun = (x0, y0, x1, y1, side, o) => { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) M.wall(x, y, side, o); };
    /* strict 180° symmetry: sym180 mirrors the authored top half; the edge
       walls sitting ON the middle line (N edges at y = 4) get their twins here */
    M.symAll = () => {
        M.sym180();
        Object.keys(M.walls).forEach(k => {
            const p = k.split(','), x = +p[0], y = +p[1], side = p[2];
            const mk = (side === 'N') ? ((S - 1 - x) + ',' + (S - y) + ',N') : ((S - x) + ',' + (S - 1 - y) + ',W');
            if (!M.walls[mk]) M.walls[mk] = Object.assign({}, M.walls[k]);
        });
    };
    /* a 1×1 solid monument + its 180° twin (even-footprint kinds such as the
       dumpster do not rotate-mirror onto the same tiles — place both by hand) */
    M.pillarSym = (kind, x, y, maxH, o) => M.monSym(kind, x, y, 1, maxH || 3, o);
    M.finishDelta = (padKey) => {
        padKey = padKey || M.cfg.base || 'grass_2';
        const sp1 = [], sp2 = [], HX = hqArenaHouse(S);   // the house tiles centred on the board (8: spawns x 2..5, nexus 3..4)
        for (let i = 0; i < 4; i++) { sp1.push({ x: HX.x0 + i, y: S - 1 }); sp2.push({ x: HX.x0 + i, y: 0 }); }
        M.spawns(sp1, sp2);
        /* protected tiles: spawn rows, egress rows, nexus zone → flat baseline,
           dry passable pad, no objects, no walls on any of their edges */
        const HAZ = new Set([MF_TID.lava, MF_TID.deep_water, MF_TID.poison_bog, MF_TID.poison, MF_TID.cloud_gap, MF_TID.chasm, MF_TID.water].filter(Boolean));
        const prot = [];
        for (let x = HX.x0; x <= HX.x1; x++) prot.push([x, 0], [x, 1], [x, S - 2], [x, S - 1]);
        prot.push([HX.n, HX.n], [HX.n + 1, HX.n], [HX.n, HX.n + 1], [HX.n + 1, HX.n + 1]);
        prot.forEach(([x, y]) => {
            if (M.hgt[y][x] !== B) { console.warn('[DeltaForge] ' + M.cfg.name + ': protected tile ' + x + ',' + y + ' was not flat — flattened'); M.h(x, y, B); }
            if (HAZ.has(M.ter[y][x])) M.t(x, y, padKey);
            delete M.underrides[x + ',' + y];
            M.clearObj(x, y);
            ['N', 'S', 'E', 'W'].forEach(side => { delete M.walls[M.wallKey(x, y, side)]; });
        });
        /* the spawn apron: finishSpawns clamps any |Δh| > 1 tile within one
           step of a spawn tile — warn so nobody authors a +2 block there */
        [sp1, sp2].forEach(list => list.forEach(p => {
            for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
                const x = p.x + dx, y = p.y + dy;
                if (M.in(x, y) && Math.abs(M.hgt[y][x] - B) > 1) console.warn('[DeltaForge] ' + M.cfg.name + ': ' + x + ',' + y + ' is too tall beside a spawn — clamped');
            }
        }));
        M.finishSpawns(padKey);
        /* the centre nexus zone: ONE authored object at the zone's NW anchor,
           placed after symmetry so it is never doubled. Arena stamps the 2×2
           nexus terrain from it (map.js _initNexusFromObjects); every mode
           without a nexus strips it and the centre stays plain floor. */
        M.objs[HX.n][HX.n] = M.objs[HX.n][HX.n].filter(e => e.oid !== MF_OID.nexus);
        M.obj(HX.n, HX.n, 'nexus');
        /* cosmetic monument kinds have no collision — never let one pretend */
        M.mons.forEach(m => { if (!MF_DELTA_SOLID_MONS.has(m.kind)) m.solid = false; });
        const entry = M.finish();
        entry.isDelta = true;
        entry.bed = M.strata.slice(); entry.underTop = M.underTop;   // the board's own bed (MOVING MAPS)
        entry.base = M.cfg.base || 'grass_2';
        entry.deltaDesc = M.deltaDesc;
        return entry;
    };
    return M;
}

/* ═══════════════════════ THE Δ BOARDS — one per launch map ═════════════════
   Coordinates: x 0..7 west→east, y 0..7 north→south. P2 row 0, P1 row 7,
   nexus x3..4 × y3..4. Author rows 0..3 only, then symAll(). Tiles (1,0),
   (1,1), (6,0), (6,1) sit on the spawn apron: trees / walls / monuments / +1
   are fine there, +2 blocks are not (finishSpawns would clamp them). */
const _MF_DELTA_BUILDERS = {};

/* Tier 1 ───────────────────────────────────────────────────────────────── */
/* THE AREA PASS (2026-09-19 — the user: "fix and revise the delta maps to look
   more like their corresponding explorable areas"): every site Δ below is a
   cut of its ENTRY PART (DOOR_HQ.siteRooms.entry → the terrain room the bay
   door lands in, HQ_AREA_SPECS / the complexes) — its floor + cliff + path
   sheets, its named features (the tiers, the pools, the streams, the walls,
   the weenie) and its props, in the forge's vocabulary. The Δ's tints are the
   room's tints; the desc names the part. The area rooms are the source of
   truth — reread the room's spec before retuning a board. */

/* MOUNT SHASTA — THE SLOPES: the timberline meadow under the cliff tiers, a
   dirt trail, the cold lake with the plank across its stream, the pines, the
   crag you climb (the hand-holds), the campfire. */
_MF_DELTA_BUILDERS.prebuilt_shasta = function () {
    const M = _mfDeltaNew({ name: 'Mount Shasta', base: 'grass_2', seed: 8101,
        tints: { cliff: '#b8b4b0', grass_2: '#7fb26a', dirt: '#9a7c58', water: '#5aa8d8', wood_planks: '#a88458' },
        desc: 'THE SLOPES — the timberline meadow under the cliff tiers, the dirt trail, the cold lake and its plank, the pines, the crag' });
    M.rect(3, 1, 4, 2, 'dirt');                              // the trail
    M.step(1, 2, 'grass_2'); M.step(0, 3, 'grass_2');        // the first tier
    M.block(0, 2, 'cliff');                                  // the crag (climb it from the tier)
    M.lake(7, 2, 'water', 2); M.lake(7, 3, 'water', 2); M.lake(6, 2, 'water', 1);   // the lake and its shallows
    M.t(6, 3, 'wood_planks');                                // the plank over the stream
    M.treeL(0, 0, 'tree_2'); M.treeL(7, 0, 'tree_3'); M.treeL(5, 3, 'tree_2');
    M.obj(1, 1, 'torch', { leaf: 'floor' });                 // the campfire
    M.symAll();
    return M.finishDelta();
};

/* STONEHENGE — THE PLAIN: the bank and ditch round the sarsen circle, the
   processional, the horseshoe of stones, the great trilithon's tier. */
_MF_DELTA_BUILDERS.prebuilt_stonehenge = function () {
    const M = _mfDeltaNew({ name: 'Stonehenge', base: 'grass_2', seed: 8102,
        tints: { ruins: '#b8b0a0', dirt: '#a08868', rock_wall_1: '#b4aa98', grass_2: '#86a860' },
        desc: 'THE PLAIN — the bank and the ditch round the circle, the processional, the sarsens in their horseshoe, the great trilithon\'s tier' });
    M.rect(3, 1, 4, 2, 'dirt');                              // the processional
    M.lake(1, 2, 'dirt', 1); M.lake(6, 2, 'dirt', 1);        // the ditch
    M.step(0, 2, 'grass_2'); M.step(0, 3, 'grass_2');        // the bank
    M.step(6, 3, 'ruins');                                   // the trilithon's tier
    M.symAll();
    M.pillarSym('monolith', 2, 2, 3); M.pillarSym('monolith', 5, 2, 3);   // the horseshoe
    M.pillarSym('monolith', 1, 3, 3); M.pillarSym('monolith', 7, 1, 3);   // the outer sarsens
    return M.finishDelta();
};

