    keys: { counter: 'hourglasses', label: 'KEYS' },

    /* Code Red (HQ plan 3.3): once a day, one STABILIZED threshold goes wrong
       — an entity filed at some other site is reported behind it. Picked
       deterministically from the local date + the employee number (the same
       Code Red all day, a different one tomorrow); the bay door and the
       threshold strobe red, the doorbell rings on the way in, the crossing
       pins that entity to the CPU roster, and clearing it (a win on that
       site the same day) pays a hazard bonus. `force` = a launch-map id
       that overrides the pick (dev: ?codered=<mapId>, no mastery needed). */
    codeRed: { bonusGold: 200, force: null },

    /* FORM 365 — Daily Office Operations Requirements (HQ plan 7.9 / Room
       247, 2026-09-11): three requirements a day, drawn like the Code Red
       from the local date + the employee number (the same sheet all day, a
       new one tomorrow) over counters the match commit already keeps — a
       win on a named site, a win by a named condition, Keys / exits in one
       crossing, a native of a named bay on the roster, an Entropy Strike, a
       Δ crossing, the day's Code Red. Each line pays `pay` Hazard Pay when
       it is met (win or lose where the line does not say WIN), the whole
       sheet pays `allBonus` on top. `hqDailyOps(profile)` reads the sheet,
       `hqDailyOpsJudge(profile, ev)` marks it at the commit (battle.js),
       the strip mirrors it, the Clock Room hangs it on the wall. `force` =
       a list of template ids for a dev run (?form365=site,keys,strike). */
    dailyOps: { pay: 120, allBonus: 150, count: 3, force: null },

    /* ── the seven bays as corridors (HQ plan 2.6, 2026-09-03) ──
       Every sector bay is a short CURVED corridor off the egress ring: the
       egress door on its inner wall, one THRESHOLD door per launch map on
       its outer wall. The rooms themselves are generated at load by
       hqBayRoom(sector) from `bayShell` + `thresholds` + `bays` — never
       hand-edit rooms.bay_*. Local polar frame per bay (deg 0 = the way
       back to the egress).
       THE CONTAINMENT RING (HQ plan 5.4a, 2026-09-07): with `ring: true`
       the bays on one floor of the egress link end to end — each end cap
       wears a fire door (`ringLeaf`) into the NEXT bay clockwise (the
       `cap_cw` door) or counter-clockwise (`cap_ccw`), ordered by the bays'
       egress-door angles on that level, wrapping. A cap door's action is
       the neighbour's SECTOR (so it wears the neighbour bay's lamp — sealed
       for a locked sector, strobing on its Code Red) and lands you at the
       matching cap of the far side. Ground floor: Bay 1 ⇄ Bay 4; the
       mezzanine ring: 2 → 5 → 7 → 3 → 6 → 2. One bay on a floor = no caps. */
    bayShell: {
        rIn: 8.5, rOut: 12.5,      // the corridor is 4 m wide, curving around its own centre
        wallH: 4.2, dadoH: 1.05,   // the egress ground-floor height: wide door frames are 3.76 m to the cap, plates sit above them
        spacing: 3.9,              // metres of outer wall per threshold door (wide panels are 3.3 m)
        endPad: 9,                 // degrees of blank wall past the last door, before the end cap
        minHalf: 24,               // the shortest corridor is ±24°
        floor: 'concrete', wall: 'stone', dado: 'oxblood', trim: 'teal', ceiling: 'ceiling',
        ring: true,                // the bays link end to end (plan 5.4a); false = dead-end caps as before
        ringLeaf: 'leaf_wired_double',   // the fire door on every linked cap (wide; the 4 m cap takes a 3.3 m panel)
        /* THE CONTAINMENT RING, stage 2 (HQ plan 5.4a, 2026-09-08): ONE
           continuous corridor per floor of the egress instead of a room per
           bay. The ring is framed in the egress's own polar frame just
           outside its drum — the ground ring behind the lower wall (r 21),
           the mezzanine ring behind the upper drum (r 24) — so every bay
           door on the egress wall is the ring's inner-wall door at the SAME
           angle, and the bay's thresholds spread along the outer wall
           either side of it. hqRingLayout(level) lays the bays out as
           SEGMENTS of the one hallway (a bay's door run is centred on its
           egress door and nudged only where two runs would collide),
           hqRingRoom(level) builds the room (kind 'bay' — the arc shell,
           the walking surface and the door placement take any span), and
           hqBayId(sector) resolves to the ring of the bay's floor, so every
           consumer (the egress door, the site rooms' way back, the panels,
           the directory, Code Red, the cast) follows without a change. The
           ring wraps only the bays' arcs (`endPadM` of blank wall past the
           outermost threshold, then a cap); with `close` the two caps wear
           the stage-1 fire door to EACH OTHER — the ring continues past the
           service core, which is not on the plan. `arc[level]` = a hand
           span override ([deg0, deg1], deg1 may pass 360; a span of 360
           closes the circle and drops the caps). Kill-switch: `on: false`
           restores the stage-1 bays (one room each, cap doors between). */
        corridor: {
            on: true,
            rings: { 0: { rIn: 21.5, rOut: 25.5, id: 'ring_g', floor: 'GROUND FLOOR' }, 1: { rIn: 24.5, rOut: 28.5, id: 'ring_m', floor: 'MEZZANINE' } },
            endPadM: 2.2,             // metres of blank outer wall past the outermost threshold, before the cap
            gapM: 2.6,                // the least outer wall between two bays' door runs (room for a cabinet)
            arc: { 0: null, 1: null },
            close: true,              // the caps wear a fire door to each other (a door-blink across the service side)
        },
    },
