            npcSpots: [{x:-11.9,z:32.9,face:180,race:'knight',say:['“Halt.” “I have a form.” “Everyone has a form. Halt anyway; it is the custom.”','“The drawbridge is down.” “Is that safe?” “It is down for you. It is not down for everyone.”']},{x:11.9,z:32.9,face:180,race:'knight'},{x:5.6,z:31.15,face:300,race:'swordfighter',say:['“Go on. Pull it.” “What happens?” “Nothing has happened yet. That is the interesting part.”','“Whoso pulleth out this sword — the rest is worn off. We assume it ends well.”']},{x:29.75,z:21.7,face:240,race:'robinhood',say:['“The orchard is the Crown’s.” “Whose Crown?” “Lapsed. Help yourself.”','“I can see the sky castle from the east wall. Nobody else can see it from anywhere. Continuity has a form for that too.”']},{x:-22.75,z:82.25,face:90,race:'knight'},{x:-12.25,z:82.25,face:270,race:'knight'},{x:-57.75,z:-120.75,face:120,race:'yeti',say:'“The loft is where the wrapping is kept. I am not allowed up the ladder.”'},{x:71.75,z:-120.75,face:0,race:'krampus'}],
            onlineSpots: [],
            lines: ['“The moat is the record. The drawbridge is the amendment.” “And the wall?” “The wall is the appendix nobody reads.”','“Which side of the portcullis is inside?” “Both. HINGE technology. No privileged side.”','“The castle in the sky.” “Where?” “North-north-east, over the wall, a third of the way up.” “I don’t see it.” “Then you are not on the wall.”','“The sword is still in the stone.” “Who does it belong to?” “The stone, at present.”','“The postern goes to the mountain.” “Which mountain?” “The one that is always behind the keep.”'],
