            agents: [],
            npcSpots: [{x:1.75,z:12.6,face:180,race:'men in black',say:['“Badge.” “I have a badge.” “I did not ask if you had one.”','“Photography is prohibited.” “I have no camera.” “Memory is discouraged.”']},{x:-8.75,z:4.9,face:20,race:'mad scientist',say:['“It is under a tarp.” “Why?” “The tarp is the classified part.”','“It flew once.” “When?” “Tuesday. Do not write down which.”']},{x:12.25,z:-15.75,face:250,race:'general',say:['“Hangar eighteen.” “There are seventeen hangars.” “Then this one is easy to find.”']},{x:15.75,z:19.25,face:270,race:'grey',say:['“…” “Is it yours?” “…” “Do you want it back?” “…” “That is a no, then.”']}],
            onlineSpots: [],
            lines: ['“Est. 1947.” “Established what?” “That there was nothing here.”','“The floor lift goes down.” “To where?” “To the D.U.M.B. Everything that goes down goes there.”','“The catwalk is for observation.” “Of what?” “Of the tarp.”','“The crane hook has been up there since ’52.” “Holding what?” “Its position.”'],
