            npcSpots: [{x:23.75,z:-18.6,face:160,race:'marksman',say:['“The lights go round.” “Whose are they?” “Ours, on the paperwork.” “And off it?” “Round.”']},{x:-29.75,z:47.25,face:0,race:'men in black'},{x:47.25,z:26.25,face:90,race:'mad scientist'},{x:-71.75,z:-50.75,face:0,race:'men in black',say:['“You are not here.” “I walked here.” “Then you walked nowhere. Carry on.”']},{x:-57.75,z:-68.25,face:270,race:'marksman',say:['“Turn back.” “I have a pass.” “Everybody has a pass. Nobody has a reason.”']},{x:-8.75,z:5.25,face:270,race:'men in black',say:['“The bus leaves at six.” “For where?” “Six.”']},{x:22.75,z:-33.25,face:180,race:'spy'},{x:50.75,z:36.75,face:0,race:'bligblog'},{x:61.25,z:8.75,face:200,race:'grey'}],
