            agents: [],
            npcSpots: [{x:817.25,z:176.75,face:30,race:'grey',say:'“The footprint was there in the previous frame. You were not.”'},{x:848.75,z:92.75,face:180,race:'men in black',say:'“The habitat is rated for six. There are two of us. Do not ask about the other four.”'},{x:827.75,z:152.25,face:220,race:'barbarella'},{x:792.75,z:173.25,face:60,race:'men in black'},{x:852.25,z:64.75,face:200,race:'grey'},{x:820.75,z:64.75,face:0,race:'grey',say:'“The rim is up there. The tape is on it. The ladder is not.”'},{x:764.75,z:110.25,face:60,race:'mantid'},{x:789.25,z:82.25,face:200,race:'voidweaver'},{x:691.25,z:131.25,face:90,race:'grey',say:'“There is no far side. There is a side you have not been shown.”'},{x:698.25,z:166.25,face:180,race:'men in black'},{x:449.75,z:-288.75,face:176,race:'grey',say:'“The pyramid is a receipt.”'},{x:309.75,z:-341.25,face:103,race:'grey',say:'“The face is a face from up here. From the ground it is a hill. From orbit it is a face again. Pick one.”'},{x:316.75,z:-295.75,face:65,race:'martian',say:'“The mouth goes to the Moon. Do not ask which side.”'},{x:372.75,z:-253.75,face:270,race:'droid'},{x:428.75,z:-257.25,face:93,race:'martian'},{x:390.25,z:-208.25,face:202,race:'martian',say:'“The rover looks behind it because we told it to. We were waving.”'},{x:449.75,z:-201.25,face:285,race:'droid'},{x:-92.75,z:180.25,face:30,race:'grey',say:'“One ice grain in the ring is square. We put it back every orbit.”'},{x:-131.25,z:162.75,face:249,race:'grey',say:'“The camp is upwind of the eye. The eye is upwind of everything else.”'},{x:-141.75,z:145.25,face:90,race:'watcher',say:'“The frame on the rim has nothing in it. Do not look at what is in it.”'},{x:-71.75,z:169.75,face:300,race:'black goo'},{x:-82.25,z:89.25,face:180,race:'android',say:'“The collar seals. Then the ship is here or it is not. There is no third reading.”'},{x:-33.25,z:162.75,face:271,race:'grey'},{x:390.25,z:281.75,face:300,race:'cosmic wraith',say:'“Eight seconds of falling. The ninth is you.”'},{x:365.75,z:267.75,face:100,race:'shadow entity',say:'“The lens bends the light round it. It does not bend the fall.”'},{x:442.75,z:260.75,face:246,race:'watcher',say:'“The camp is upstream of the drop. Everything is upstream of the drop.”'},{x:421.75,z:225.75,face:174,race:'occulus',say:'“The screen shows the drop. The drop shows the screen. Do not stand between them.”'},{x:327.25,z:299.25,face:86,race:'cosmic wraith'}],
            onlineSpots: [],
