    const A = HQ_PARTY_RULES.autoHeal, steps = [];
    const vit = m => hqPartyVitals(m, units && units[m.id]);
    const snap = () => r.members.map(m => { const v = vit(m); return { id: m.id, hp: v.hp, hpMax: v.hpMax, mp: v.mp, mpMax: v.mpMax, down: v.down }; });
    const before = snap();
