        const rv = spellSteps('revive', (sp, c) => c.v.mp >= (sp.cost | 0)).sort((a, b) => (a.sp.cost | 0) - (b.sp.cost | 0))[0];
        if (rv && cast(rv.c, rv.sp, m)) continue;
